/* Local presentation layer only. No application imports, API clients or live forms. */
window.LakePublic = (() => {
  const art = (name, cls = '') => `<img class="${cls}" src="assets/${name}.svg" alt="" aria-hidden="true">`;
  const link = (route, label, style = '') => `<a class="button ${style}" href="#/${route}">${label}<span aria-hidden="true">↗</span></a>`;
  const logo = `<a class="brand" href="#/home" aria-label="LakeLife home"><img src="assets/lakelife-logo-on-ink.svg" alt="LakeLife"></a>`;
  const header = route => `<header class="site-header"><div class="shell header-inner">${logo}<button class="menu-toggle" aria-expanded="false" aria-controls="public-nav" data-action="menu">Menu <span aria-hidden="true">☰</span></button><nav id="public-nav" class="site-nav" aria-label="Main navigation">${[['services','Services'],['for-parks','For park owners'],['how-it-works','How it works']].map(([r,l])=>`<a href="#/${r}" ${route===r?'class="active" aria-current="page"':''}>${l}</a>`).join('')}<a class="nav-cta" href="#/portal">Open my portal <span aria-hidden="true">↗</span></a></nav></div></header>`;
  const footer = () => `<footer class="site-footer"><div class="shell"><div class="footer-grid"><div>${logo}<p>A little less to manage.<br>A little more life at the lake.</p>${art('lakelife-wave-divider','footer-wave')}</div><div><h4>EXPLORE LAKELIFE</h4><ul><li><a href="#/services">Lake-home services</a></li><li><a href="#/for-parks">For park owners</a></li><li><a href="#/how-it-works">How it works</a></li><li><a href="#/marketing">Park-owner introduction</a></li></ul></div><div><h4>YOUR NEXT STEP</h4><ul><li><a href="#/portal">Open my portal</a></li><li><a href="#/get-started">Ask for a walkthrough</a></li><li>LakeLife.ai</li></ul></div></div><div class="footer-bottom"><span>LakeLife · Big Long, Pretty &amp; Big Turkey Lakes, Indiana</span><span>Local concept preview · Example screens · Availability varies</span></div></div></footer>`;
  const cta = (title = 'Let’s make lake life feel lighter.', body = 'Tell us about your property or park. We’ll start with what you need.') => `<section class="cta-band"><div class="shell"><div><h2>${title}</h2><p>${body}</p></div>${link('get-started','Ask for a walkthrough','gold')}</div></section>`;
  const faq = items => `<div class="faq">${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
  const commonFAQ = [
    ['Does Seasonal Autopilot book work for me?', 'It suggests the next seasonal visit. You choose whether to book or skip it. A suggested or requested date is not a confirmed appointment.'],
    ['When will I know the price?', 'Some services show a price when you request them. Others need a crew quote first and will show “Price pending.” You see your customer price before a charge.'],
    ['Where are services available?', 'LakeLife is focused on Big Long, Pretty and Big Turkey Lakes in Indiana. Specific services depend on your property, season and available crews. Confirm availability before planning around a visit.'],
    ['Is park rent the same as a household service bill?', 'No. Park rent and shared charges stay with your park account. Optional household services have their own requests and charges. Online payment options depend on what is enabled for your park and account.']
  ];
  const parkFAQ = [
    ['What does getting started look like?', 'Start with a walkthrough of your rent roll, billing process and park needs. Setup is guided, and your actual configuration and payment readiness are checked before any rollout.'],
    ['What if a resident pays at the office?', 'A resident can report a payment they made outside the portal. The report stays pending until the park reviews it. A report alone never reduces the balance or moves money.'],
    ['Can residents use LakeLife for their own services?', 'Where available, residents can request optional household services separately. Their service charges are not mixed into park rent or exposed as park-office service pricing.'],
    ['Will online rent collection work immediately?', 'Online payment methods appear only when the required setup and capabilities are enabled. A portal design or a completed walkthrough does not mean payment collection is live.']
  ];
  const parkWindow = () => `<div class="preview-window"><div class="window-bar">${art('lakelife-logo-on-ink')}<span>PARK OFFICE</span></div><div class="window-content"><span class="eyebrow">LAKESIDE PARK · EXAMPLE</span><h3>Your day, in view.</h3><div class="window-summary"><div><b>4</b><span>Occupied lots</span></div><div><b>$640</b><span>Balance outstanding</span></div><div><b>1</b><span>Payment to review</span></div></div><div class="window-row"><div><strong>Payment report · Lot 01</strong><small>$100 reported · Not yet credited</small></div><span class="pill gold">Review</span></div><div class="window-row"><div><strong>October rent roll</strong><small>Charges, receipts and balances together</small></div><span class="pill teal">View roll</span></div><div class="window-row"><div><strong>Resident issue · Lot 03</strong><small>Follow the park’s recorded updates</small></div><span class="pill">Open</span></div></div><div class="window-label">Illustrative dashboard · Synthetic records, amounts and activity</div></div>`;
  const homeWindow = () => `<div class="preview-window"><div class="window-bar">${art('lakelife-logo-on-ink')}<span>MY LAKE HOME</span></div><div class="window-content"><span class="eyebrow">THE SEASON AHEAD · EXAMPLE</span><h3>One less thing to remember.</h3><div class="window-row"><div><strong>🍂 Seasonal closing</strong><small>Suggested next visit · You choose what happens</small></div><span class="pill gold">Review</span></div><div class="window-row"><div><strong>🌊 Pier removal</strong><small>Oct 28 · Example confirmed appointment</small></div><span class="pill teal">Scheduled</span></div><div class="window-row"><div><strong>🌱 Lawn care request</strong><small>Requested date is not yet confirmed</small></div><span class="pill">Price pending</span></div><a class="text-link" href="#/homeowner">Explore the sample portal <span aria-hidden="true">→</span></a></div><div class="window-label">Illustrative dashboard · No work has been booked</div></div>`;
  const serviceItems = [
    ['house','Seasonal home care','Opening and closing help for the change of seasons.'],
    ['pier','Piers & docks','Installation and removal, coordinated around lake conditions.'],
    ['lift','Boat lifts','Seasonal installation and removal requests.'],
    ['boat','Boat winterization','Prepare your boat for the quieter months.'],
    ['toys','Toys & storage','Explore available seasonal care and storage options.'],
    ['mow','Lawn care','Weekly mow-and-blow and available yard services.'],
    ['clean','Housekeeping','Help keeping your lake home ready for your next stay.']
  ];
  const home = () => `<section class="hero"><div class="shell hero-content"><span class="eyebrow gold">LOCAL CARE. LESS TO COORDINATE.</span><h1>Your LakeLife,<br><span>Automated.</span></h1><p class="intro">Your home. Your seasons. One place to keep up.<br>LakeLife brings service requests, seasonal suggestions and visit records together—so the next step is easy to see.</p><div class="actions">${link('services','Explore lake-home services','gold')}${link('for-parks','I own or run a park','ghost')}</div><p class="hero-note">Seasonal visits are suggested. You choose to book or skip.</p></div><span class="image-credit">Illustrative lakefront scene</span>${art('lakelife-waves','hero-wave')}</section><div class="location-band"><div class="shell"><span class="location-label">ROOTED RIGHT HERE</span><div class="lake-names"><span>Big Long Lake</span><span>Pretty Lake</span><span>Big Turkey Lake</span></div><small>Confirm service availability for your property.</small></div></div><section class="section"><div class="shell"><div class="section-heading"><div><span class="eyebrow">A PLACE FOR EVERY PART OF LAKE LIFE</span><h2>Find your way in.</h2></div><p>From the park office to your own front porch, start with what matters to you.</p></div><div class="role-grid">${[
    ['01','house','Park owners','Bring the rent roll, resident records and park work into a clearer daily view.','for-parks','Explore LakeLife for parks'],
    ['02','pier','Homeowners','Request local services, review seasonal suggestions and follow each visit.','services','Find care for your home'],
    ['03','renter','Renters','See your park bill, review payment records and follow office updates.','portal','Find your resident portal']
  ].map(([n,a,t,p,r,l])=>`<article class="role-tile"><div class="tile-top"><span class="number">${n} /</span>${art(a)}</div><h3>${t}</h3><p>${p}</p><a class="text-link" href="#/${r}">${l} <span aria-hidden="true">→</span></a></article>`).join('')}</div></div></section><section class="section white"><div class="shell"><div class="section-heading"><div><span class="eyebrow">THE WORK BEHIND THE WEEKEND</span><h2>Keep the lake in lake life.</h2></div><a class="text-link" href="#/services">Explore all services <span aria-hidden="true">→</span></a></div><div class="service-strip">${[serviceItems[0],serviceItems[1],serviceItems[5],serviceItems[6]].map(([a,t,p])=>`<a href="#/services" class="service-tile"><div class="service-art">${art(a)}<span class="mini-flag">Explore</span></div><h3>${t}</h3><p>${p}</p></a>`).join('')}</div></div></section><section class="section"><div class="shell split-editorial"><div class="editorial-copy"><span class="eyebrow">A CLEARER NEXT STEP</span><h2>From “we should”<br>to “here’s where it stands.”</h2><p>No guessing whether a suggestion is a booking, or whether a request has a price. LakeLife keeps those details visible.</p><div class="steps">${[['01','Tell us what needs doing.','Choose a service and share the details about your property.'],['02','Review the next step.','See a price or a pending quote, then follow scheduling updates.'],['03','Keep the record.','Review the visit status and required completion photos when available.']].map(([n,t,p])=>`<div class="step"><span class="step-number">${n}</span><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></div>${homeWindow()}</div></section><section class="section white"><div class="shell"><span class="eyebrow">GOOD QUESTIONS. CLEAR ANSWERS.</span><h2>Before you begin.</h2>${faq(commonFAQ)}</div></section>${cta()}`;
  const marketing = () => `<section class="marketing-hero"><div class="shell"><div><span class="eyebrow">FOR THE PEOPLE BEHIND THE PARK</span><h1>Your park.<br>A clearer day.</h1><p class="intro">A rent roll you can read. Payment reports you can review. Residents who can see their own bill. Meet a calmer way to keep the park moving.</p><div class="actions">${link('get-started','Ask for a park walkthrough','gold')}<a class="text-link" href="#/park">Explore the sample portal →</a></div><p class="small-copy muted" style="margin-top:18px">Start with your park’s needs. Setup and availability are reviewed together.</p></div>${parkWindow()}</div></section><section class="section white"><div class="shell"><div class="feature-line">${[['01','Know what needs you.','Start with pending payment reports, open resident issues and the current rent roll.'],['02','Give renters a clear view.','Show their charges, confirmed receipts, remaining balance and recorded office updates.'],['03','Keep the money separate.','Park rent, LakeLife fees and optional household services each keep their own record.']].map(([n,t,p])=>`<div><span class="eyebrow">${n} /</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></section><section class="section"><div class="shell split-editorial"><div class="editorial-copy"><span class="eyebrow">BUILT AROUND AN ORDINARY PARK DAY</span><h2>Less “what happened?”<br>More “what’s next?”</h2><p>When someone says they paid at the office, you need a record you can check. When a resident asks about a charge, they need a bill that explains it.</p><p>LakeLife gives each side a place to see the status—without treating an unverified report as money received.</p><a class="text-link" href="#/for-parks">See the park-owner experience →</a></div><div class="panel" style="padding:32px"><span class="eyebrow">A SHARED MOMENT · SAMPLE WORKFLOW</span><div class="journey-list"><div class="journey-row done"><span class="journey-dot">1</span><div><b>A renter reports a payment.</b><p>“I paid $100 at the office.” The report is pending.</p></div></div><div class="journey-row done"><span class="journey-dot">2</span><div><b>The office checks its records.</b><p>The balance stays the same while the report is reviewed.</p></div></div><div class="journey-row"><span class="journey-dot">3</span><div><b>The confirmed record is reflected.</b><p>Only a confirmed receipt changes the bill. Confirming a record does not transfer funds.</p></div></div></div><a class="button quiet" href="#/renter">See the renter’s view <span aria-hidden="true">→</span></a></div></div></section><section class="section white"><div class="shell"><span class="eyebrow">START WITH THE DETAILS</span><h2>A fit for your park?</h2>${faq(parkFAQ)}</div></section>${cta('Let’s walk through your park.','Bring your current process. We’ll look at the rent roll, the renter experience and the setup your park needs.')}`;
  const services = () => `<section class="public-page-head"><div class="shell page-intro-row"><div><span class="eyebrow">LOCAL SERVICES · AROUND YOUR LAKE LIFE</span><h1>Care for the place<br>you come to unwind.</h1><p class="intro">Explore the work LakeLife helps coordinate. Your property, season and available crews determine what can be requested.</p></div>${art('pier')}</div></section><section class="section" style="padding-top:0"><div class="shell"><div class="public-grid">${serviceItems.map(([a,t,p])=>`<article class="public-card">${art(a)}<h3>${t}</h3><p>${p}</p><a class="text-link" href="#/get-started">Check availability <span aria-hidden="true">→</span></a></article>`).join('')}</div><p class="small-copy muted" style="margin-top:24px">Illustrations describe service categories. They are not a promise of available crews, a confirmed date or a fixed price. Some requests require a quote.</p></div></section><section class="section white"><div class="shell split-editorial"><div class="editorial-copy"><span class="eyebrow">THE DETAILS MATTER</span><h2>A request is the start<br>of the conversation.</h2><p>Share your property details and preferred date. If a crew quote is needed, the request stays marked “Price pending.” Scheduling and pricing updates remain separate.</p><a class="text-link" href="#/how-it-works">Understand the steps →</a></div>${homeWindow()}</div></section>${cta()}`;
  const parks = () => `<section class="public-page-head"><div class="shell"><span class="eyebrow">PARK OWNERS & OFFICE TEAMS</span><h1>See the park.<br>Know the next step.</h1><p class="intro">A practical home for the rent roll, resident records, shared costs and work around the park.</p><div class="actions" style="margin-top:26px">${link('get-started','Ask for a walkthrough','gold')}${link('park','Explore the sample portal','light')}</div></div></section><section class="section" style="padding-top:10px"><div class="shell">${[
    ['01','Start with today.','Pending payment reports and open resident issues come first. The day’s view points you toward records that need attention.'],
    ['02','Make the rent roll readable.','See charges, confirmed receipts and balances by lot. Keep a resident’s “I already paid” report distinct until the office reviews it.'],
    ['03','Show how a charge was shared.','Review shared-cost allocations alongside their supporting records. Your park’s configured billing rules determine the actual charges.'],
    ['04','Give renters their own view.','Residents can see their own bill and recorded updates. Optional household services stay separate from the park’s rent and service records.'],
    ['05','Coordinate work on site.','Follow park service requests and the schedule for assigned work. Suggested dates, requested dates and confirmed appointments keep their own meaning.']
  ].map(([n,t,p])=>`<article class="article-section"><span class="number">${n}</span><h2>${t}</h2><p>${p}</p></article>`).join('')}</div></section><section class="section white"><div class="shell"><span class="eyebrow">BEFORE YOUR FIRST ROLLOUT</span><h2>Fit first. Then setup.</h2>${faq(parkFAQ)}</div></section>${cta('Put your actual workflow on the table.','Walk through LakeLife using your park’s needs, then decide what makes sense to adopt.')}`;
  const how = () => `<section class="public-page-head"><div class="shell"><span class="eyebrow">HOW LAKELIFE WORKS</span><h1>Clear steps.<br>No mystery in between.</h1><p class="intro">Here’s what a service request means at each stage—and what it doesn’t mean yet.</p></div></section><section class="section" style="padding-top:0"><div class="shell">${[
    ['01','Start with your property.','Choose the service and share the details a crew will need. Your account needs a working email and verified mobile before the first booking.'],
    ['02','Request what you need.','Select your preferred date. A request is not a confirmed appointment. Local availability and, for water work, lake-season rules still apply.'],
    ['03','Watch for pricing and scheduling.','Some requests have a price; others need a crew quote. A pending price stays pending. You see your customer price before a charge.'],
    ['04','Review the visit record.','Follow status updates and review required completion photos when available. A completion record is distinct from payment settlement.'],
    ['05','Choose the next seasonal visit.','Seasonal Autopilot can suggest the next visit. You decide to book or skip. Suggestions do not create automatic bookings.']
  ].map(([n,t,p])=>`<article class="article-section"><span class="number">${n}</span><h2>${t}</h2><p>${p}</p></article>`).join('')}</div></section><section class="section white"><div class="shell"><span class="eyebrow">RUNNING A PARK?</span><h2>Your day starts a little differently.</h2><p class="muted" style="max-width:630px;margin:23px 0">Begin with the rent roll and records that need review. Residents see their own bill, while the office keeps the park-wide view. Payment readiness is part of your setup.</p>${link('for-parks','See the park workflow')}</div></section>${cta()}`;
  const gateway = () => `<section class="gateway"><span class="eyebrow">WELCOME TO LAKELIFE</span><h1>A little closer to<br>your kind of lake life.</h1><p class="intro">Find the right starting point for your home or park.</p><div class="gateway-grid">${[
    ['house','Park owner / office','Rent roll, residents and what needs attention.','park'],
    ['renter','Renter','Your park bill, payment records and office updates.','renter'],
    ['pier','Homeowner','Your requests, seasonal care and visit records.','homeowner'],
    ['boat','New to LakeLife?','Explore services or arrange a park walkthrough.','get-started']
  ].map(([a,t,p,r])=>`<a class="gateway-tile" href="#/${r}">${art(a)}<div><h2>${t}</h2><p>${p}</p></div><span class="gateway-arrow" aria-hidden="true">↗</span></a>`).join('')}</div><div class="help-strip"><span>Getting your park started?</span><a class="text-link" href="#/marketing">Meet LakeLife for parks →</a></div><p class="small-copy muted" style="margin-top:26px">Preview note: these links open sample screens. In the platform, sign-in and account permissions determine which records you can access.</p></section>`;
  const contact = () => `<section class="section"><div class="shell split-form"><div><span class="eyebrow">LET’S START WITH YOUR PLACE</span><h1>Take a look.<br>Talk it through.</h1><p class="intro">Tell us what you manage and what you’d like help coordinating. A walkthrough is a chance to see whether LakeLife fits.</p><ul class="scope-points"><li>Walk through the screens that matter to you.</li><li>Discuss service availability and park setup.</li><li>Review pricing and payment readiness before rollout.</li></ul><div style="margin-top:35px">${art('house')}</div></div><div class="form-panel"><h2>Ask for a walkthrough</h2><form id="walkthrough-form"><div class="field"><label for="contact-name">Your name</label><input id="contact-name" name="name" autocomplete="off" placeholder="Example: Alex Morgan" required maxlength="80"></div><div class="field"><label for="contact-email">Email</label><input id="contact-email" name="email" type="email" autocomplete="off" placeholder="alex@example.com" required maxlength="120"></div><div class="field"><label for="contact-role">I’m here as a…</label><select id="contact-role" name="role"><option>Park owner or office team</option><option>Homeowner</option><option>Renter</option></select></div><div class="field"><label for="contact-note">What would you like to explore?</label><textarea id="contact-note" name="note" maxlength="1000" placeholder="Your park, property or the work you need help with."></textarea></div><button class="button" type="submit">Preview my request <span aria-hidden="true">→</span></button><p class="contact-notice">Local design preview: use example details. This prepares an on-screen draft only. Nothing is sent or saved.</p></form></div></div></section>`;
  const pages = {home,marketing,services,'for-parks':parks,'how-it-works':how,portal:gateway,'get-started':contact};
  return {art,link,logo,render: route => `${header(route)}<main id="main" tabindex="-1">${(pages[route]||home)()}</main>${footer()}`};
})();
